/**
 * Wear logging — the one write path every wear-derived surface reads from.
 *
 * Times worn, cost-per-wear, last worn, the Fit Diary grid, streaks, "most
 * worn" and "gathering dust" are all views over wear_logs. Nothing wrote to it
 * before this.
 */

/** The button states itself: an instruction before, a fact after. */
export function wearLabel(worn: boolean): string {
  return worn ? "Worn today" : "Wear this today";
}

/**
 * `worn_on` is a DATE column, compared against the user's LOCAL date key — a
 * UTC comparison would move an evening wear in an eastern timezone onto the
 * next day, which is the same class of bug the daily drop already avoids.
 */
export function isWornToday(logs: { worn_on: string }[], today: string): boolean {
  return logs.some((l) => l.worn_on === today);
}

/**
 * Where a regenerated set starts numbering, given the indices already pinned.
 *
 * A worn outfit is pinned: `saveDailyLooks` leaves it out of the day's delete so
 * that wearing a look and then regenerating cannot destroy what you actually
 * wore (the FK had no ON DELETE action, so it used to fail outright). But
 * `outfits_daily_unique` is `(user_id, occasion, generated_on, look_index)`, so
 * the fresh set has to be numbered past the survivors.
 *
 * Indices only ever move forward — gaps left by a previous regenerate are not
 * reused, because reusing one would collide with a look pinned in between.
 */
export function freshIndexStart(pinned: (number | null)[]): number {
  const used = pinned.filter((i): i is number => typeof i === "number");
  return used.length === 0 ? 0 : Math.max(...used) + 1;
}

// The embed is one-to-one but PostgREST types it loosely; normalise once.
const rows: ItemRow[] = (links ?? [])
  .map((l) => (Array.isArray(l.items) ? l.items[0] : l.items))
  .filter((i): i is ItemRow => Boolean(i));
if (rows.length === 0) notFound();

const signed = await signItemImages(rows.map(displayPath));

// The stored geometry is what makes the detail stage identical to the look the
// user tapped. Rows written before the daily drop have no layout — fall back
// to computing one rather than dropping the flat-lay entirely.
const stored = (outfit.layout ?? {}) as { pieces?: { itemId: string; slot: Slot }[] };
const slotById = new Map((stored.pieces ?? []).map((p) => [p.itemId, p.slot]));
const computed = layoutForLook(rows.map((r) => ({ category: r.category })));

const pieces: DetailPiece[] = rows.map((i, idx) => ({
  id: i.id,
  name: i.name ?? i.subcategory ?? i.category,
  brand: i.brand,
  category: i.category,
  imageUrl: signed.get(displayPath(i)) ?? "",
  slot: slotById.get(i.id) ?? computed[idx],
}));

const { data: logs } = await supabase.from("wear_logs").select("worn_on").eq("outfit_id", id);

// Same timezone rule as the action — localDateFor takes a zone, never a bare Date.
const { data: profile } = await supabase
  .from("profiles")
  .select("location_timezone")
  .eq("id", user.id)
  .single();
const today = localDateFor(new Date(), profile?.location_timezone ?? "UTC");

const weather = outfit.weather_snapshot as { tempC?: number; condition?: string } | null;

import type { Slot } from "./types";

// Deterministic flat-lay templates (Decision D6). Each category maps to a slot
// (percentages within the stage). Invariants — enforced by layout.test.ts and
// authored to survive real photo cutouts (never the placeholder SVGs):
//   • every slot is in-bounds (0 ≤ x, x+w ≤ 100; same for y/h) → cutouts never clip
//   • |rotation| ≤ 6° → composed, not chaotic
//   • the anchor (outerwear else top) is the largest slot, highest z, and staggers first

type PieceLite = { category: string };

const SLOTS = {
  ANCHOR: { xPct: 6, yPct: 8, wPct: 46, hPct: 64, rotationDeg: -5, z: 3 },
  UPPER: { xPct: 56, yPct: 10, wPct: 36, hPct: 34, rotationDeg: 4, z: 2 },
  SIDE: { xPct: 58, yPct: 46, wPct: 34, hPct: 44, rotationDeg: -3, z: 2 },
  LOWER: { xPct: 18, yPct: 74, wPct: 40, hPct: 20, rotationDeg: 6, z: 2 },
  CORNER: { xPct: 6, yPct: 76, wPct: 14, hPct: 16, rotationDeg: -6, z: 1 },
} satisfies Record<string, Slot>;

type Role = keyof typeof SLOTS;

function roleFor(category: string, hasOuter: boolean): Role {
  switch (category) {
    case "Outerwear":
      return "ANCHOR";
    case "Tops":
      return hasOuter ? "UPPER" : "ANCHOR";
    case "Bottoms":
      return "SIDE";
    case "Shoes":
      return "LOWER";
    default:
      return "CORNER"; // Accessories (and any extra)
  }
}

export function layoutForLook(pieces: PieceLite[]): Slot[] {
  const hasOuter = pieces.some((p) => p.category === "Outerwear");
  return pieces.map((p) => ({ ...SLOTS[roleFor(p.category, hasOuter)] }));
}

/** Indices in re-lay stagger order: the anchor (highest z, ties → largest area) first, then input order. */
export function staggerOrder(slots: Slot[]): number[] {
  let anchor = 0;
  for (let i = 1; i < slots.length; i++) {
    const a = slots[anchor];
    const b = slots[i];
    if (b.z > a.z || (b.z === a.z && b.wPct * b.hPct > a.wPct * a.hPct)) anchor = i;
  }
  const rest = slots.map((_, i) => i).filter((i) => i !== anchor);
  return [anchor, ...rest];
}

