import { thumbnailPieces, MAX_THUMB_PIECES } from "../thumbnail";

const p = (category: string, imageUrl = `${category}.webp`) => ({ category, imageUrl });

test("a full look is capped at three pieces", () => {
  const picked = thumbnailPieces([
    p("Tops"),
    p("Bottoms"),
    p("Shoes"),
    p("Accessories"),
    p("Outerwear"),
  ]);
  expect(picked).toHaveLength(MAX_THUMB_PIECES);
});

// At a ~45px cell every extra cutout costs legibility, so the three that
// describe a look best win: one upper body, one lower, one shoe.
test("it keeps one upper piece, the bottoms and the shoes", () => {
  const picked = thumbnailPieces([p("Tops"), p("Bottoms"), p("Shoes"), p("Accessories")]);
  expect(picked.map((x) => x.imageUrl)).toEqual(["Tops.webp", "Bottoms.webp", "Shoes.webp"]);
});

test("outerwear outranks the top for the single upper slot", () => {
  const picked = thumbnailPieces([p("Tops"), p("Outerwear"), p("Bottoms"), p("Shoes")]);
  expect(picked.map((x) => x.imageUrl)).toEqual(["Outerwear.webp", "Bottoms.webp", "Shoes.webp"]);
});

test("a sparse look renders what it has rather than nothing", () => {
  expect(thumbnailPieces([p("Tops")])).toHaveLength(1);
  expect(thumbnailPieces([])).toEqual([]);
});

// A piece with no signed URL must be dropped here, not rendered as <img src="">.
test("pieces with no image are dropped", () => {
  const picked = thumbnailPieces([p("Tops", ""), p("Bottoms"), p("Shoes")]);
  expect(picked.map((x) => x.imageUrl)).toEqual(["Bottoms.webp", "Shoes.webp"]);
});

test("every piece carries in-bounds flat-lay geometry", () => {
  for (const { slot } of thumbnailPieces([p("Outerwear"), p("Bottoms"), p("Shoes")])) {
    expect(slot.xPct).toBeGreaterThanOrEqual(0);
    expect(slot.yPct).toBeGreaterThanOrEqual(0);
    expect(slot.xPct + slot.wPct).toBeLessThanOrEqual(100);
    expect(slot.yPct + slot.hPct).toBeLessThanOrEqual(100);
  }
});

// Accessories and fragrance are the CORNER slot at 14% — three pixels wide in a
// diary cell, and never what you remember an outfit by.
test("a look of only accessories still yields a thumbnail", () => {
  expect(thumbnailPieces([p("Accessories"), p("Fragrance")]).length).toBeGreaterThan(0);
});

import { layoutForLook } from "@/lib/generator/layout";
import type { DiaryPiece } from "./month";

/**
 * How many cutouts a diary cell shows.
 *
 * A diary cell is ~45×54px on a 390px phone (7 columns, 7px gaps, 18px page
 * padding), so a five-piece look gives each garment about 20px and the flat-lay
 * reads as overlapping colour blobs. Three keeps distinct silhouettes while
 * still showing the outfit's palette — which is what a month grid is actually
 * scanned for ("which day was the camel one?"). The full look is one tap away.
 */
export const MAX_THUMB_PIECES = 3;

type Candidate = { category: string; imageUrl: string };

/** One upper-body piece, the bottoms, the shoes — in that reading order. */
const UPPER = ["Outerwear", "Tops"];

/**
 * Choose and position the cutouts for one day's cell.
 *
 * Geometry comes from `layoutForLook`, the same deterministic templates the
 * full-size flat-lay uses, so a thumbnail is a scaled-down version of the look
 * the user tapped rather than a second, divergent layout system. The templates
 * are percentage-based, so they survive the shrink unchanged.
 */
export function thumbnailPieces(pieces: Candidate[]): DiaryPiece[] {
  // A piece the storage layer could not sign is dropped here rather than
  // rendered as <img src="">, which React treats as an error.
  const usable = pieces.filter((p) => Boolean(p.imageUrl));

  const upper = UPPER.map((c) => usable.find((p) => p.category === c)).find(Boolean);
  const bottoms = usable.find((p) => p.category === "Bottoms");
  const shoes = usable.find((p) => p.category === "Shoes");

  const chosen = [upper, bottoms, shoes].filter((p): p is Candidate => Boolean(p));

  // A look made only of accessories has none of the three preferred slots, and
  // an empty cell would read as "nothing logged" for a day that was logged.
  if (chosen.length === 0) {
    chosen.push(...usable.slice(0, MAX_THUMB_PIECES));
  }

  const capped = chosen.slice(0, MAX_THUMB_PIECES);
  const slots = layoutForLook(capped);
  return capped.map((p, i) => ({ imageUrl: p.imageUrl, slot: slots[i] }));
}

import { render, screen, within } from "@testing-library/react";
import { DiaryGrid } from "../diary-grid";
import { buildMonth } from "@/lib/diary/month";
import { thumbnailPieces } from "@/lib/diary/thumbnail";

const pieces = thumbnailPieces([
  { category: "Tops", imageUrl: "top.webp" },
  { category: "Bottoms", imageUrl: "btm.webp" },
  { category: "Shoes", imageUrl: "shoe.webp" },
]);

const cells = buildMonth(2026, 7, "2026-07-24", [
  { worn_on: "2026-07-09", outfitId: "o1", pieces },
]);

function renderGrid(over: Partial<React.ComponentProps<typeof DiaryGrid>> = {}) {
  return render(
    <DiaryGrid
      cells={cells}
      monthLabel="July 2026"
      streak={3}
      prevHref="/calendar?m=2026-06"
      nextHref="/calendar?m=2026-08"
      {...over}
    />,
  );
}

test("renders a Monday-first weekday header", () => {
  renderGrid();
  const header = screen.getByTestId("weekday-header");
  expect(within(header).getAllByText(/^Mon$/i)[0]).toBeInTheDocument();
  expect(within(header).getByText(/^Sun$/i)).toBeInTheDocument();
});

test("a logged day links to its outfit; an empty day does not", () => {
  renderGrid();
  expect(screen.getByRole("link", { name: /9 July/i })).toHaveAttribute("href", "/outfits/o1");
  expect(screen.queryByRole("link", { name: /10 July/i })).not.toBeInTheDocument();
});

// getByText("3") would also match the day-3 cell — scope to the pill.
test("the streak is shown with its unit", () => {
  renderGrid();
  const pill = screen.getByTestId("streak-pill");
  expect(within(pill).getByText("3")).toBeInTheDocument();
  expect(within(pill).getByText(/days/i)).toBeInTheDocument();
});

test("a zero streak is not rendered as a boast", () => {
  renderGrid({ streak: 0 });
  expect(screen.queryByTestId("streak-pill")).not.toBeInTheDocument();
});

test("a logged day renders its look as stacked cutouts", () => {
  renderGrid();
  const cell = screen.getByRole("link", { name: /9 July/i });
  expect(within(cell).getAllByRole("presentation")).toHaveLength(3);
});

// wear_logs.outfit_id is ON DELETE SET NULL, so a wear outlives its outfit.
// The day is still part of the record and the streak — it just goes nowhere.
test("a wear whose outfit is gone marks the day but is not a link", () => {
  const orphaned = buildMonth(2026, 7, "2026-07-24", [
    { worn_on: "2026-07-09", outfitId: null, pieces },
  ]);
  renderGrid({ cells: orphaned });
  expect(screen.queryByRole("link", { name: /9 July/i })).not.toBeInTheDocument();
  expect(screen.getByTestId("cell-2026-07-09")).toBeInTheDocument();
});

test("month navigation points at the neighbouring months", () => {
  renderGrid();
  expect(screen.getByRole("link", { name: /previous month/i })).toHaveAttribute(
    "href",
    "/calendar?m=2026-06",
  );
  expect(screen.getByRole("link", { name: /next month/i })).toHaveAttribute(
    "href",
    "/calendar?m=2026-08",
  );
});

test("the month label and title head the screen", () => {
  renderGrid();
  expect(screen.getByText("July 2026")).toBeInTheDocument();
  expect(screen.getByRole("heading", { name: /fit diary/i })).toBeInTheDocument();
});

// A month with nothing logged must explain itself rather than show a bare grid.
test("an empty month explains where entries come from", () => {
  renderGrid({ cells: buildMonth(2026, 7, "2026-07-24", []) });
  expect(screen.getByText(/wear a look/i)).toBeInTheDocument();
});

test("a month with wears does not show the empty-state footnote", () => {
  renderGrid();
  expect(screen.queryByText(/wear a look/i)).not.toBeInTheDocument();
});

import Link from "next/link";
import type { CSSProperties } from "react";
import { Kicker } from "@/components/ui-fitcheck/kicker";
import type { Cell, DiaryPiece } from "@/lib/diary/month";

/** Monday-first, matching `buildMonth`'s leading pad. */
const DOWS = ["Mon", "Tue", "Wed", "Thu", "Fri", "Sat", "Sun"];

function Flame() {
  return (
    <svg width="14" height="16" viewBox="0 0 24 28" fill="var(--color-brand)" aria-hidden="true">
      <path d="M12 0c2 5-3 7-3 12a3 3 0 006 0c0-1 0-2-1-3 3 2 5 5 5 9a9 9 0 11-18 0c0-7 7-9 7-15 2 1 3 3 3 5 1-3 2-5 1-8z" />
    </svg>
  );
}

/** `2026-07-09` → `9 July` — the cell's accessible name. */
function dayLabel(key: string): string {
  const [y, m, d] = key.split("-").map(Number);
  return new Intl.DateTimeFormat("en-GB", { day: "numeric", month: "long", timeZone: "UTC" }).format(
    new Date(Date.UTC(y, m - 1, d)),
  );
}

/**
 * A day's look, laid out with the same percentage geometry as the full-size
 * flat-lay — so the cell is a miniature of the screen it opens, not a second
 * layout system that can drift from it.
 */
function Thumbnail({ pieces }: { pieces: DiaryPiece[] }) {
  return (
    <>
      {pieces.map((p, i) => {
        const s = p.slot;
        const style: CSSProperties = {
          position: "absolute",
          left: `${s.xPct}%`,
          top: `${s.yPct}%`,
          width: `${s.wPct}%`,
          height: `${s.hPct}%`,
          zIndex: s.z,
          transform: `rotate(${s.rotationDeg}deg)`,
        };
        return (
          // eslint-disable-next-line @next/next/no-img-element
          <img
            // Not next/image: these are short-lived signed Supabase URLs, and the
            // optimizer caches by URL — a rotating signature would mean a paid
            // transformation per view. Same reasoning as the closet card.
            key={`${p.imageUrl}-${i}`}
            src={p.imageUrl}
            alt=""
            role="presentation"
            loading="lazy"
            decoding="async"
            className="object-contain"
            style={style}
          />
        );
      })}
    </>
  );
}

function DayCell({ cell }: { cell: Cell }) {
  if (!cell.inMonth) return <div aria-hidden="true" />;

  const worn = Boolean(cell.log);
  const body = (
    <>
      {cell.log && <Thumbnail pieces={cell.log.pieces} />}
      <span
        className={
          worn
            ? "absolute bottom-[3px] right-[5px] text-[9px] text-foreground/50"
            : "text-[12px] text-muted-dim"
        }
      >
        {cell.day}
      </span>
    </>
  );

  // Today is ringed in rust — the screen's one rust element besides the streak
  // flame, both of which are the same "you, now" signal.
  const shell = [
    "relative flex aspect-[0.82] items-center justify-center overflow-hidden rounded-[10px]",
    worn ? "bg-surface-2" : "bg-surface-1",
    cell.isToday
      ? "shadow-[inset_0_0_0_1.5px_var(--color-brand)]"
      : "shadow-[inset_0_0_0_1px_var(--hairline-2)]",
  ].join(" ");

  // A wear outlives its outfit (`wear_logs.outfit_id` is ON DELETE SET NULL), so
  // a logged day is only a link when there is still something to open.
  if (cell.log?.outfitId) {
    return (
      <Link
        href={`/outfits/${cell.log.outfitId}`}
        aria-label={dayLabel(cell.key)}
        data-testid={`cell-${cell.key}`}
        className={shell}
      >
        {body}
      </Link>
    );
  }
  return (
    <div data-testid={`cell-${cell.key}`} className={shell}>
      {body}
    </div>
  );
}

/**
 * The Fit Diary (`Fitcheck.dc.html:436-477`) — a month of what you actually
 * wore. Presentational: every date here is already the user's local date key,
 * decided by the route.
 */
export function DiaryGrid({
  cells,
  monthLabel,
  streak,
  prevHref,
  nextHref,
}: {
  cells: Cell[];
  monthLabel: string;
  streak: number;
