import { initials, handleFrom, paletteFor } from "../identity";

describe("initials", () => {
  test("initials come from the display name", () => {
    expect(initials("Mykhailo Khimich", "m@x.com")).toBe("MK");
    expect(initials("Cher", "c@x.com")).toBe("C");
  });

  test("a missing name falls back to the email, never to an empty circle", () => {
    expect(initials(null, "icurafu333@gmail.com")).toBe("I");
    expect(initials("", "icurafu333@gmail.com")).toBe("I");
  });

  test("initials are at most two characters even for long names", () => {
    expect(initials("Ana Maria Sofia Ferreira", "a@x.com")).toHaveLength(2);
  });

  test("extra whitespace does not produce blank initials", () => {
    expect(initials("  Mykhailo   Khimich  ", "m@x.com")).toBe("MK");
  });

  // The avatar is a 62px circle with nothing else in it — an empty one reads as
  // a broken image rather than a person.
  test("a name of only whitespace still yields a letter", () => {
    expect(initials("   ", "icurafu333@gmail.com")).toBe("I");
  });

  test("initials are upper-cased however the name was typed", () => {
    expect(initials("mykhailo khimich", "m@x.com")).toBe("MK");
  });
});

describe("handleFrom", () => {
  test("the handle derives from the email local-part", () => {
    expect(handleFrom("icurafu333@gmail.com")).toBe("@icurafu333");
  });

  // A handle is shown on screen and will eventually reach a share card, so it
  // must not carry characters that read as punctuation noise.
  test("dots and plus-addressing are stripped", () => {
    expect(handleFrom("first.last+fitcheck@gmail.com")).toBe("@firstlast");
  });

  test("it never returns a bare @", () => {
    expect(handleFrom("@weird.com").length).toBeGreaterThan(1);
    expect(handleFrom("")).toMatch(/^@\w+/);
  });
});

describe("paletteFor", () => {
  test("a known archetype has a palette; an unknown one still returns swatches", () => {
    expect(paletteFor("Old Money").length).toBeGreaterThan(0);
    expect(paletteFor(null).length).toBeGreaterThan(0);
  });

  test("every palette entry is a renderable hex", () => {
    for (const c of paletteFor("Streetwear")) expect(c).toMatch(/^#[0-9a-f]{6}$/i);
    for (const c of paletteFor(null)) expect(c).toMatch(/^#[0-9a-f]{6}$/i);
  });

  // Every archetype the onboarding quiz can produce must resolve to something
  // deliberate rather than silently falling back.
  test.each(["Old Money", "Smart Casual", "Preppy", "Streetwear"])(
    "%s — the quiz's own archetype — has its own palette",
    (a) => {
      expect(paletteFor(a).length).toBeGreaterThan(0);
    },
  );

  // These are the --color-dna-* tokens in globals.css. Hard-coding a second set
  // here is how the hub and the Style DNA card drift apart.
  test("palettes are drawn from the DNA tokens", () => {
    const DNA = ["#ede6d8", "#2c3a4c", "#b89a6a", "#6e6f52", "#b86a47"];
    for (const a of ["Old Money", "Preppy", null]) {
      for (const c of paletteFor(a)) expect(DNA).toContain(c.toLowerCase());
    }
  });
});

/**
 * The DNA swatch tokens, mirrored from `--color-dna-*` in `app/globals.css`.
 *
 * Kept as one named set so the profile hub and the Style DNA card cannot drift
 * apart — a second hard-coded palette somewhere else is exactly how two screens
 * end up disagreeing about what an archetype looks like.
 */
const DNA = {
  cream: "#ede6d8",
  navy: "#2c3a4c",
  camel: "#b89a6a",
  olive: "#6e6f52",
  rust: "#b86a47",
} as const;

/** The four archetypes the onboarding quiz can produce (`lib/onboarding/questions.ts`). */
const PALETTES: Record<string, string[]> = {
  "Old Money": [DNA.cream, DNA.navy, DNA.camel],
  "Smart Casual": [DNA.camel, DNA.olive, DNA.cream],
  Preppy: [DNA.navy, DNA.cream, DNA.rust],
  Streetwear: [DNA.olive, DNA.navy, DNA.rust],
};

/** The full set, for a profile that has not answered the quiz. */
const FALLBACK = Object.values(DNA);

/**
 * One or two letters for the avatar circle.
 *
 * Falls back to the email rather than rendering an empty circle, which reads as
 * a broken image rather than as a person.
 */
export function initials(name: string | null, email: string): string {
  const words = (name ?? "").trim().split(/\s+/).filter(Boolean);
  if (words.length > 0) {
    return words
      .slice(0, 2)
      .map((w) => w[0]!.toUpperCase())
      .join("");
  }
  const first = email.replace(/[^a-z0-9]/gi, "")[0];
  return (first ?? "F").toUpperCase();
}

/**
 * A display handle derived from the email's local-part.
 *
 * `profiles` has no `handle` column and adding one needs an edit flow and a
 * uniqueness rule, which belong with the Settings account row rather than here.
 * Isolated in this one function so replacing it later is a one-line change.
 *
 * Plus-addressing and dots are stripped: `first.last+fitcheck@…` reading as
 * `@first.last+fitcheck` looks like a bug, and the suffix leaks that the address
 * was tagged.
 */
export function handleFrom(email: string): string {
  const local = email.split("@")[0] ?? "";
  const cleaned = local.split("+")[0]!.replace(/[^a-z0-9_]/gi, "").toLowerCase();
  return `@${cleaned || "fitcheck"}`;
}

/** Swatches for an archetype; the full DNA set when there is no answer yet. */
export function paletteFor(archetype: string | null): string[] {
  if (!archetype) return FALLBACK;
  return PALETTES[archetype] ?? FALLBACK;
}

import { render, screen, within } from "@testing-library/react";
import { ProfileHub } from "../profile-hub";

const props = {
  name: "Mykhailo",
  handle: "@icurafu333",
  initials: "M",
  archetype: "Old Money",
  palette: ["#ede6d8", "#2c3a4c"],
  tier: "free" as const,
  stats: { pieces: 24, outfits: 9, streak: 3 },
  links: [
    { href: "/style-dna", label: "Style DNA", desc: "Your archetype, shareable", ready: true },
    { href: "/outfits", label: "Saved Outfits", desc: "Looks you kept", ready: false },
  ],
};

test("identity renders with initials, name and handle", () => {
  render(<ProfileHub {...props} />);
  expect(screen.getByText("M")).toBeInTheDocument();
  expect(screen.getByText("Mykhailo")).toBeInTheDocument();
  expect(screen.getByText("@icurafu333")).toBeInTheDocument();
});

test("the stat trio shows counts with their labels", () => {
  render(<ProfileHub {...props} />);
  const stats = screen.getByTestId("stat-trio");
  expect(within(stats).getByText("24")).toBeInTheDocument();
  expect(within(stats).getByText(/pieces/i)).toBeInTheDocument();
  expect(within(stats).getByText(/streak/i)).toBeInTheDocument();
});

// The closet cap is NOT shown here. Consistent with the reroll meter: a visible
// allowance makes a free user think about the limit constantly, and 50 is far
// enough away that most never approach it.
test("the pieces count does not advertise the free closet cap", () => {
  render(<ProfileHub {...props} />);
  expect(screen.getByTestId("stat-trio")).not.toHaveTextContent(/\/\s*50|of 50/);
});

// `outfits` counts looks WORN, not looks generated. The outfits table holds
// every look the generator ever produced (three per drop, plus styled looks and
// every past day), so counting rows would show a number in the hundreds that
// describes the generator rather than the user.
test("the outfits stat is labelled as what was worn", () => {
  render(<ProfileHub {...props} />);
  expect(screen.getByTestId("stat-trio")).toHaveTextContent(/worn/i);
});

test("the archetype card links through to Style DNA", () => {
  render(<ProfileHub {...props} />);
  expect(screen.getByRole("link", { name: /old money/i })).toHaveAttribute("href", "/style-dna");
});

test("an unbuilt destination is not a link — it says Soon", () => {
  render(<ProfileHub {...props} />);
  expect(screen.queryByRole("link", { name: /saved outfits/i })).not.toBeInTheDocument();
  expect(screen.getByText(/soon/i)).toBeInTheDocument();
});

describe("the Pro card", () => {
  // The price is EUR. The design says £5 and the plan said render it verbatim;
  // that is superseded for the price only — every other price in the app renders
  // in euro, and £5 beside a €3.00 cost-per-wear is a visible inconsistency.
  test("states the price in euro, not the design's pounds", () => {
    render(<ProfileHub {...props} />);
    const card = screen.getByTestId("pro-card");
    expect(card).toHaveTextContent(/€5\/mo/);
    expect(card).not.toHaveTextContent(/£/);
  });

  test("keeps the design's pitch verbatim", () => {
    render(<ProfileHub {...props} />);
    expect(screen.getByTestId("pro-card")).toHaveTextContent(
      /unlimited daily looks, packing mode & cost-per-wear analytics/i,
    );
  });

  // This card is where every gate in the app now sends people, so the one-line
  // pitch is not enough — someone who just hit a wall needs to see what they
  // would actually get.
  test("lists what Pro actually unlocks", () => {
    render(<ProfileHub {...props} />);
    const card = screen.getByTestId("pro-card");
    expect(card).toHaveTextContent(/rerolls/i);
    expect(card).toHaveTextContent(/closet/i);
    expect(card).toHaveTextContent(/around any piece/i);
  });

  test("is inert — billing does not exist yet", () => {
    render(<ProfileHub {...props} />);
    expect(screen.queryByRole("link", { name: /go pro/i })).not.toBeInTheDocument();
    expect(screen.queryByRole("button", { name: /go pro/i })).not.toBeInTheDocument();
  });

  // Selling Pro to someone who already pays is the clearest possible sign that
  // nothing is reading their tier.
  test("a Pro subscriber is not sold the upgrade", () => {
    render(<ProfileHub {...props} tier="pro" />);
    const card = screen.getByTestId("pro-card");
    expect(card).not.toHaveTextContent(/go pro/i);
    expect(card).toHaveTextContent(/active/i);
  });
});

import Link from "next/link";
import { Kicker } from "@/components/ui-fitcheck/kicker";
import type { Tier } from "@/lib/billing/tiers";

export type HubLink = {
  href: string;
  label: string;
  desc: string;
  /** False until the destination exists on `main`. */
  ready: boolean;
};

/**
 * What Pro unlocks, in the order MONETISATION.md §3 lists it.
 *
 * The design's card carries only the one-line pitch, which was enough when this
 * screen was the only place Pro was mentioned. It is now the destination for
 * every gate in the app, so someone arriving here has just been refused
 * something and needs to see what they would actually get.
 */
const PRO_BENEFITS = [
  "Unlimited rerolls, any occasion",
  "Build a look around any piece",
  "An unlimited closet",
  "Packing mode for trips",
  "Cost-per-wear analytics",
  "Gap analysis — what to buy next",
  "Unlimited saved outfits",
];

function StatCell({ value, label }: { value: string; label: string }) {
  return (
    <div className="flex-1 px-[6px] py-4 text-center">
      <div className="font-serif text-[24px] text-foreground">{value}</div>
      <div className="mt-[5px] text-[10px] uppercase tracking-[0.1em] text-muted-dim">{label}</div>
    </div>
  );
}

function LinkRow({ link }: { link: HubLink }) {
  const body = (
    <>
      <div className="size-[38px] shrink-0 rounded-[10px] bg-[#201b18]" aria-hidden="true" />
      <div className="min-w-0 flex-1">
        <div className="text-[15px] text-foreground">{link.label}</div>
        <div className="mt-[2px] text-[12px] text-muted-foreground">{link.desc}</div>
      </div>
      {link.ready ? (
        <span className="text-[20px] text-muted-dim" aria-hidden="true">
          ›
        </span>
      ) : (
        <span className="text-[10px] uppercase tracking-[0.14em] text-muted-dim">Soon</span>
      )}
    </>
  );

  const shell =
    "flex items-center gap-[14px] rounded-[14px] bg-surface-1 px-4 py-[15px] shadow-[inset_0_0_0_1px_var(--hairline-2)]";

  // An unready row is NOT a link. Two of the four bottom tabs used to 404 for
  // exactly this reason (BUGS.md #5); it should not repeat one level down.
  return link.ready ? (
    <Link href={link.href} className={shell}>
      {body}
    </Link>
  ) : (
    <div className={`${shell} opacity-60`}>{body}</div>
  );
}

/**
 * The profile hub (`Fitcheck.dc.html:659-702`).
 *
 * Presentational: every count is computed by the route.
 */
export function ProfileHub({
  name,
  handle,
  initials,
  archetype,
  palette,
  tier,
  stats,
  links,
  children,
}: {
  name: string;
  handle: string;
  initials: string;
  archetype: string | null;
  palette: string[];
  tier: Tier;
  /** `outfits` is looks WORN, not looks generated — see the route. */
  stats: { pieces: number; outfits: number; streak: number };
  links: HubLink[];
  /** Sign-out, until Settings owns it. */
  children?: React.ReactNode;
}) {
  const isPro = tier === "pro";

  return (
    <div className="flex-1 overflow-y-auto px-[22px] pb-[120px] screen-top">
      <div className="flex items-center gap-[14px]">
        <div className="grid size-[62px] shrink-0 place-items-center rounded-full font-serif text-[22px] text-value shadow-[inset_0_0_0_1px_var(--hairline-6)] [background:linear-gradient(150deg,#2a2622,#191518)]">
          {initials}
        </div>
        <div className="min-w-0 flex-1">
          <h1 className="font-serif text-[25px]/[1] text-foreground">{name}</h1>
          <p className="mt-[5px] text-[13px] text-muted-foreground">{handle}</p>
        </div>
      </div>

      {/* The closet cap is deliberately absent. Same reasoning as the reroll
          meter: a visible allowance makes a free user think about the limit
          constantly, and 50 is far enough out that most never approach it. */}
      <div
        data-testid="stat-trio"
        className="mt-[22px] flex overflow-hidden rounded-[14px] bg-surface-1 shadow-[inset_0_0_0_1px_var(--hairline-2)]"
      >
        <StatCell value={String(stats.pieces)} label="Pieces" />
        <StatCell value={String(stats.outfits)} label="Outfits worn" />
        <StatCell value={String(stats.streak)} label="Day streak" />
      </div>

      <Link
        href="/style-dna"
        className="relative mt-[13px] block overflow-hidden rounded-[16px] p-5 shadow-[inset_0_0_0_1px_rgba(184,106,71,0.18)] [background:radial-gradient(120%_120%_at_82%_8%,#241d18,#161517)]"
      >
        <span className="text-[10px] uppercase tracking-[0.22em] text-[#b89a6a]">Your archetype</span>
        <div className="mt-[6px] font-serif text-[30px] text-foreground">
          {archetype ?? "Not set yet"}
        </div>
        <div className="mt-[14px] flex gap-[5px]">
          {palette.map((c) => (
            <div
              key={c}
              className="size-[30px] rounded-[7px] shadow-[inset_0_0_0_1px_rgba(255,255,255,0.07)]"
              style={{ background: c }}
            />
          ))}
        </div>
        <span className="absolute right-[18px] top-6 text-[20px] text-muted-dim" aria-hidden="true">
          ›
        </span>
      </Link>

      <div className="mt-[13px] flex flex-col gap-[10px]">
        {links.map((l) => (
          <LinkRow key={l.label} link={l} />
        ))}
      </div>

      {/* Inert by design: there is no checkout, and a button that goes nowhere
          is worse than none. This card is the explanation, not the purchase. */}
      <div
        data-testid="pro-card"
        className="mt-[13px] rounded-[16px] p-5 [background:linear-gradient(120deg,#b86a47,#9a5236)]"
      >
        <div className="font-serif text-[21px] italic text-[#1a0f09]">Fitcheck Pro</div>

        {isPro ? (
          <>
            <p className="mt-[5px] text-[13px]/[1.4] text-[rgba(26,15,9,0.82)]">
              Active — everything below is yours.
            </p>
            <ul className="mt-3 flex flex-col gap-[6px]">
              {PRO_BENEFITS.map((b) => (
                <li key={b} className="text-[13px]/[1.35] text-[rgba(26,15,9,0.82)]">
                  {b}
                </li>
              ))}
            </ul>
          </>
        ) : (
          <>
            {/* The design's pitch, verbatim — it names packing mode, which does
                not exist yet. Deliberate while nothing can be bought; it must be
                built before Pro is actually sold. */}
            <p className="mt-[5px] max-w-[84%] text-[13px]/[1.4] text-[rgba(26,15,9,0.82)]">
              Unlimited daily looks, packing mode &amp; cost-per-wear analytics.
            </p>
            <ul className="mt-3 flex flex-col gap-[6px]">
              {PRO_BENEFITS.map((b) => (
                <li key={b} className="text-[13px]/[1.35] text-[rgba(26,15,9,0.82)]">
                  {b}
                </li>
              ))}
            </ul>
            <div className="mt-[13px] inline-block rounded-full bg-canvas px-[17px] py-[9px] text-[13px] font-semibold text-foreground">
              Go Pro · €5/mo
            </div>
          </>
        )}
      </div>

      {children && <div className="mt-[13px]">{children}</div>}
    </div>
  );
}

